    async def fetch_pairs_for_token_addresses(self, tokenAddresses: List[str], params={}) -> List[Any]:
        addresses = self.get_unique_token_addresses(tokenAddresses)
        maxBatchSize = self.safe_integer(self.options, 'maxTokenAddressesPerRequest', 30)
        allPairs: List[dict] = []
        offset = 0
        while(offset < len(addresses)):
            batch = addresses[offset:offset + maxBatchSize]
            pairs = await self.fetch_pairs_for_token_address_batch(batch, params)
            for j in range(0, len(pairs)):
                allPairs.append(pairs[j])
            offset = offset + maxBatchSize
        return allPairs

    async def fetch_pairs_for_tokens_v1_batch(self, tokenAddresses: List[str], params={}) -> List[Any]:
        if len(tokenAddresses) == 0:
            return []
        chainId = self.get_configured_chain_id()
        request: dict = {
            'chainId': chainId,
            'tokenAddresses': ','.join(tokenAddresses),
        }
        response = await self.publicGetTokensV1ChainIdTokenAddresses(self.extend(request, params))
        return self.parse_token_pairs_response(response)

    async def fetch_pairs_for_tokens_v1(self, tokenAddresses: List[str], params={}) -> List[Any]:
        addresses = self.get_unique_token_addresses(tokenAddresses)
        maxBatchSize = self.safe_integer(self.options, 'maxTokenAddressesPerRequest', 30)
        allPairs: List[dict] = []
        offset = 0
        while(offset < len(addresses)):
            batch = addresses[offset:offset + maxBatchSize]
            pairs = await self.fetch_pairs_for_tokens_v1_batch(batch, params)
            for j in range(0, len(pairs)):
                allPairs.append(pairs[j])
            offset = offset + maxBatchSize
